input.content:
@import "tailwindcss";

@theme {
  --color-bloom-milk: #FFF8F4;
  --color-lumi-coral: #FF6F5E;
  --color-petal-mint: #A8E6CF;
  --color-glow-peach: #FFCBA4;
  --color-sunshine-butter: #FFE566;
  --color-aqua-bloom: #5BC8D0;
  --color-deep-petal: #2D3A35;
  --color-soft-cloud: #EDF6F9;

  --font-heading: "Nunito", system-ui, sans-serif;
  --font-body: "DM Sans", system-ui, sans-serif;
  --font-accent: "Fredoka One", "Nunito", system-ui, sans-serif;

  --radius-bloom: 24px;

  --shadow-card: 0 4px 16px rgba(45, 58, 53, 0.08);
  --shadow-card-lg: 0 8px 28px rgba(45, 58, 53, 0.12);
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  color: var(--color-deep-petal);
  background: var(--color-bloom-milk);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  letter-spacing: -0.02em;
}

.font-accent {
  font-family: var(--font-accent);
  letter-spacing: 0.10em;
  text-transform: uppercase;
}

/* ----- Reveal animation utilities ----- */
.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.9s cubic-bezier(0.22, 1, 0.36, 1), transform 0.9s cubic-bezier(0.22, 1, 0.36, 1);
  will-change: opacity, transform;
}
.reveal.is-visible {
  opacity: 1;
  transform: translateY(0);
}
.reveal-delay-1 { transition-delay: 80ms; }
.reveal-delay-2 { transition-delay: 160ms; }
.reveal-delay-3 { transition-delay: 240ms; }
.reveal-delay-4 { transition-delay: 320ms; }
.reveal-delay-5 { transition-delay: 400ms; }
.reveal-delay-6 { transition-delay: 480ms; }
.reveal-delay-7 { transition-delay: 560ms; }
.reveal-delay-8 { transition-delay: 640ms; }

.fade-in-up {
  animation: fadeInUp 1.0s cubic-bezier(0.22, 1, 0.36, 1) both;
}
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes bloomFloat {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  50% { transform: translateY(-12px) rotate(2deg); }
}
.bloom-float {
  animation: bloomFloat 8s ease-in-out infinite;
  transform-origin: center;
}

@keyframes spinSlow {
  to { transform: rotate(360deg); }
}
.spin-slow { animation: spinSlow 40s linear infinite; }
.spin-slow-rev { animation: spinSlow 60s linear infinite reverse; }

@keyframes pulseGlow {
  0%, 100% { box-shadow: 0 0 0 0 rgba(255, 111, 94, 0.35); }
  50% { box-shadow: 0 0 0 14px rgba(255, 111, 94, 0); }
}
.pulse-glow { animation: pulseGlow 2.4s ease-in-out infinite; }

@keyframes marquee {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}
.marquee-track {
  animation: marquee 38s linear infinite;
}

@keyframes shimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}

@keyframes stickerWobble {
  0%, 100% { transform: rotate(-8deg); }
  50% { transform: rotate(8deg); }
}
.sticker-wobble { animation: stickerWobble 4s ease-in-out infinite; }

@keyframes drift {
  0%, 100% { transform: translate(0,0); }
  50% { transform: translate(8px, -10px); }
}
.drift { animation: drift 12s ease-in-out infinite; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 16px;
  border-radius: 9999px;
  padding: 0.85rem 1.75rem;
  transition: transform 0.25s ease, background-color 0.25s ease, color 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
  cursor: pointer;
  line-height: 1;
  white-space: nowrap;
}
.btn:hover { transform: translateY(-2px) scale(1.02); }
.btn:focus-visible {
  outline: 3px solid var(--color-aqua-bloom);
  outline-offset: 3px;
}
.btn-primary {
  background: var(--color-lumi-coral);
  color: white;
  box-shadow: 0 8px 24px rgba(255, 111, 94, 0.25);
}
.btn-primary:hover {
  background: #FF5A47;
  box-shadow: 0 12px 32px rgba(255, 111, 94, 0.35);
}
.btn-secondary {
  background: transparent;
  color: var(--color-aqua-bloom);
  border: 2px solid var(--color-aqua-bloom);
}
.btn-secondary:hover {
  background: var(--color-aqua-bloom);
  color: white;
}
.btn-ghost-light {
  background: transparent;
  color: white;
  border: 2px solid white;
}
.btn-ghost-light:hover {
  background: rgba(255,255,255,0.15);
}
.btn-light {
  background: white;
  color: var(--color-lumi-coral);
}
.btn-light:hover {
  background: var(--color-sunshine-butter);
  color: var(--color-deep-petal);
}
.btn-dark {
  background: var(--color-deep-petal);
  color: white;
}
.btn-dark:hover {
  background: #1c2622;
}

/* Input fields */
.field {
  width: 100%;
  border-radius: 12px;
  background: var(--color-bloom-milk);
  border: 2px solid var(--color-petal-mint);
  padding: 0.85rem 1rem;
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--color-deep-petal);
  transition: border-color 0.25s ease, box-shadow 0.25s ease, transform 0.2s ease;
}
.field:focus {
  outline: none;
  border-color: var(--color-aqua-bloom);
  box-shadow: 0 0 0 4px rgba(91, 200, 208, 0.18);
}
.field-label {
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 14px;
  color: var(--color-deep-petal);
  letter-spacing: 0.01em;
  display: block;
  margin-bottom: 6px;
}

/* Underline grow link */
.link-underline {
  position: relative;
  display: inline-block;
}
.link-underline::after {
  content: '';
  position: absolute;
  left: 0; bottom: -3px;
  height: 2px; width: 100%;
  background: currentColor;
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}
.link-underline:hover::after { transform: scaleX(1); }

/* Card hover lift */
.lift-card {
  transition: transform 0.4s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}
.lift-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-card-lg);
}

/* Word reveal on hero */
.word-reveal {
  display: inline-block;
  overflow: hidden;
  vertical-align: bottom;
}
.word-reveal > span {
  display: inline-block;
  transform: translateY(110%);
  animation: wordUp 0.9s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
@keyframes wordUp {
  to { transform: translateY(0); }
}

/* Smooth scroll for horizontal carousels */
.no-scrollbar::-webkit-scrollbar { display: none; }
.no-scrollbar { scrollbar-width: none; }

/* FAQ accordion content transition */
.accordion-content {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}
.accordion-content.open {
  grid-template-rows: 1fr;
}
.accordion-content > div {
  overflow: hidden;
}

/* Marquee fade edges */
.marquee-mask {
  -webkit-mask-image: linear-gradient(90deg, transparent 0%, black 8%, black 92%, transparent 100%);
          mask-image: linear-gradient(90deg, transparent 0%, black 8%, black 92%, transparent 100%);
}

/* Floating big headline text behind cards */
.text-bleed-coral {
  color: var(--color-lumi-coral);
}

