import { createSignal, onMount, onCleanup } from 'solid-js';

const links = [
  { label: 'Home', href: '/' },
  { label: 'Brand', href: '/brand.html' },
  { label: 'Products', href: '/products.html' },
  { label: 'Sustainability', href: '/sustainability.html' },
  { label: 'Contact', href: '/contact.html' },
];

export default function Nav(props) {
  const current = props.current ?? 'home';
  const [scrolled, setScrolled] = createSignal(false);
  const [open, setOpen] = createSignal(false);

  onMount(() => {
    const onScroll = () => setScrolled(window.scrollY > 8);
    onScroll();
    window.addEventListener('scroll', onScroll, { passive: true });
    onCleanup(() => window.removeEventListener('scroll', onScroll));
  });

  const isActive = (href) => {
    if (href === '/' && current === 'home') return true;
    if (href !== '/' && href.includes(current)) return true;
    return false;
  };

  return (
    <header
      class={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        scrolled() ? 'backdrop-blur-md bg-bloom-milk/85 shadow-[0_4px_20px_rgba(45,58,53,0.06)]' : 'bg-transparent'
      }`}
    >
      <nav class="max-w-7xl mx-auto px-5 sm:px-8 flex items-center justify-between h-16 lg:h-20">
        <a href="/" class="flex items-center gap-2 group">
          <span class="w-9 h-9 rounded-full bg-lumi-coral grid place-items-center text-white font-accent text-base shadow-[0_4px_12px_rgba(255,111,94,0.35)] transition-transform group-hover:rotate-12">
            <svg width="22" height="22" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <circle cx="12" cy="12" r="3" fill="#FFE566" />
              <g stroke="white" stroke-width="1.6" stroke-linecap="round">
                <path d="M12 4v3" /><path d="M12 17v3" />
                <path d="M4 12h3" /><path d="M17 12h3" />
                <path d="M6.3 6.3l2.1 2.1" /><path d="M15.6 15.6l2.1 2.1" />
                <path d="M6.3 17.7l2.1-2.1" /><path d="M15.6 8.4l2.1-2.1" />
              </g>
            </svg>
          </span>
          <span class="font-heading font-extrabold text-deep-petal text-lg tracking-tight">
            Lumi <span class="text-lumi-coral">&</span> Bloom
          </span>
        </a>

        <div class="hidden lg:flex items-center gap-8">
          {links.map((l) => (
            <a
              href={l.href}
              class={`relative font-body font-medium text-[15px] transition-colors hover:text-lumi-coral ${
                isActive(l.href) ? 'text-lumi-coral' : 'text-deep-petal'
              }`}
            >
              {l.label}
              {isActive(l.href) && (
                <span class="absolute -bottom-1.5 left-0 right-0 h-[3px] bg-lumi-coral rounded-full" />
              )}
            </a>
          ))}
        </div>

        <div class="hidden lg:flex items-center gap-3">
          <a href="/products.html" class="btn btn-primary !py-2.5 !px-5 !text-[14px]">Shop Now</a>
        </div>

        <button
          aria-label="Toggle menu"
          class="lg:hidden w-10 h-10 rounded-full bg-deep-petal text-white grid place-items-center"
          onClick={() => setOpen(!open())}
        >
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round">
            {open() ? (
              <>
                <path d="M6 6l12 12" /><path d="M18 6l-12 12" />
              </>
            ) : (
              <>
                <path d="M4 7h16" /><path d="M4 12h16" /><path d="M4 17h16" />
              </>
            )}
          </svg>
        </button>
      </nav>

      {open() && (
        <div class="lg:hidden bg-bloom-milk border-t border-deep-petal/10 px-5 py-4 space-y-2 shadow-md">
          {links.map((l) => (
            <a
              href={l.href}
              class={`block py-2 font-body font-medium ${
                isActive(l.href) ? 'text-lumi-coral' : 'text-deep-petal'
              }`}
            >
              {l.label}
            </a>
          ))}
          <a href="/products.html" class="btn btn-primary w-full mt-3">Shop Now</a>
        </div>
      )}
    </header>
  );
}

