// All inline-SVG illustrations for Lumi & Bloom.
// Each component returns a self-contained SVG so it can be reused across pages.

export function BloomMotif(props) {
  const size = props.size ?? 480;
  return (
    <svg
      viewBox="0 0 480 480"
      width={size}
      height={size}
      xmlns="http://www.w3.org/2000/svg"
      class={props.class}
      aria-hidden="true"
    >
      <defs>
        <radialGradient id="bloomCore" cx="50%" cy="50%" r="50%">
          <stop offset="0%" stop-color="#FFFBEA" />
          <stop offset="60%" stop-color="#FFE566" />
          <stop offset="100%" stop-color="#FFCBA4" />
        </radialGradient>
        <linearGradient id="petalA" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#FF8E7E" />
          <stop offset="100%" stop-color="#FF6F5E" />
        </linearGradient>
        <linearGradient id="petalB" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stop-color="#FFCBA4" />
          <stop offset="100%" stop-color="#FF8E7E" />
        </linearGradient>
      </defs>

      {/* outer petals */}
      <g class="spin-slow" style="transform-origin: 240px 240px;">
        {Array.from({ length: 12 }).map((_, i) => {
          const angle = (i * 360) / 12;
          return (
            <ellipse
              cx="240"
              cy="100"
              rx="34"
              ry="86"
              fill="url(#petalA)"
              opacity="0.9"
              transform={`rotate(${angle} 240 240)`}
            />
          );
        })}
      </g>
      {/* inner petals */}
      <g class="spin-slow-rev" style="transform-origin: 240px 240px;">
        {Array.from({ length: 8 }).map((_, i) => {
          const angle = (i * 360) / 8 + 22.5;
          return (
            <ellipse
              cx="240"
              cy="148"
              rx="22"
              ry="60"
              fill="url(#petalB)"
              opacity="0.92"
              transform={`rotate(${angle} 240 240)`}
            />
          );
        })}
      </g>
      {/* leaf accents */}
      <g class="drift" style="transform-origin: 240px 240px;">
        {[40, 130, 220, 310].map((a) => (
          <path
            d="M240 50 q-10 18 0 36 q10 -18 0 -36 z"
            fill="#A8E6CF"
            transform={`rotate(${a} 240 240) translate(0 -50)`}
          />
        ))}
      </g>
      {/* center glow */}
      <circle cx="240" cy="240" r="90" fill="url(#bloomCore)" />
      <circle cx="240" cy="240" r="46" fill="#FFF8F4" opacity="0.55" />
      <circle cx="240" cy="240" r="18" fill="#FFE566" />
      {/* tiny sparkles */}
      <g fill="#FFE566">
        <circle cx="120" cy="80" r="5" />
        <circle cx="380" cy="120" r="4" />
        <circle cx="400" cy="340" r="6" />
        <circle cx="80" cy="340" r="4" />
        <circle cx="60" cy="200" r="3" />
        <circle cx="420" cy="220" r="3" />
      </g>
    </svg>
  );
}

export function LeafSprigPattern(props) {
  return (
    <svg
      width="100%"
      height="100%"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
      class={props.class}
    >
      <defs>
        <pattern id="leafSprig" width="160" height="160" patternUnits="userSpaceOnUse">
          <g fill={props.color ?? '#2D3A35'} opacity={props.opacity ?? 0.12}>
            <path d="M20 30 q10 -12 22 0 q-10 12 -22 0z" />
            <path d="M80 60 q12 -16 28 0 q-12 16 -28 0z" transform="rotate(35 95 65)" />
            <path d="M30 100 q10 -12 22 0 q-10 12 -22 0z" transform="rotate(-30 40 105)" />
            <circle cx="110" cy="20" r="3" />
            <circle cx="60" cy="80" r="2" />
            <circle cx="20" cy="130" r="2" />
            <circle cx="130" cy="130" r="3" />
            <path d="M120 100 q12 -16 28 0 q-12 16 -28 0z" transform="rotate(60 130 105)" />
          </g>
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#leafSprig)" />
    </svg>
  );
}

export function DotsPattern(props) {
  return (
    <svg width="100%" height="100%" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
      <defs>
        <pattern id="tinyDots" width="48" height="48" patternUnits="userSpaceOnUse">
          <g fill={props.color ?? '#FFF8F4'} opacity={props.opacity ?? 0.06}>
            <circle cx="6" cy="6" r="2" /><circle cx="18" cy="6" r="2" /><circle cx="30" cy="6" r="2" />
            <circle cx="6" cy="18" r="2" /><circle cx="18" cy="18" r="2" /><circle cx="30" cy="18" r="2" />
            <circle cx="6" cy="30" r="2" /><circle cx="18" cy="30" r="2" /><circle cx="30" cy="30" r="2" />
          </g>
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#tinyDots)" />
    </svg>
  );
}

export function HandsAndFlower(props) {
  return (
    <svg viewBox="0 0 200 200" width={props.size ?? 180} height={props.size ?? 180} xmlns="http://www.w3.org/2000/svg" class={props.class} aria-hidden="true">
      {/* hands */}
      <g fill="#FFCBA4" stroke="#2D3A35" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round">
        <path d="M40 140 q-4 -28 16 -38 q14 -8 32 -2 l4 24 q-22 8 -28 26 q-2 14 8 22 q-22 4 -32 -32z" />
        <path d="M160 140 q4 -28 -16 -38 q-14 -8 -32 -2 l-4 24 q22 8 28 26 q2 14 -8 22 q22 4 32 -32z" />
      </g>
      {/* flower stem */}
      <line x1="100" y1="120" x2="100" y2="78" stroke="#2D3A35" stroke-width="2.5" stroke-linecap="round" />
      {/* leaf */}
      <path d="M100 100 q-12 -2 -14 -14 q14 -2 14 14z" fill="#A8E6CF" stroke="#2D3A35" stroke-width="2.2" stroke-linejoin="round" />
      {/* flower petals */}
      <g fill="#FF8E7E" stroke="#2D3A35" stroke-width="2.2">
        <circle cx="100" cy="58" r="14" />
        <circle cx="82" cy="68" r="11" />
        <circle cx="118" cy="68" r="11" />
        <circle cx="88" cy="50" r="10" />
        <circle cx="112" cy="50" r="10" />
      </g>
      <circle cx="100" cy="60" r="6" fill="#FFE566" stroke="#2D3A35" stroke-width="2" />
    </svg>
  );
}

export function GlobeVine(props) {
  return (
    <svg viewBox="0 0 220 220" width={props.size ?? 200} height={props.size ?? 200} xmlns="http://www.w3.org/2000/svg" class={props.class} aria-hidden="true">
      {/* globe */}
      <circle cx="110" cy="110" r="74" fill="#A8E6CF" stroke="#2D3A35" stroke-width="2.5" />
      <ellipse cx="110" cy="110" rx="74" ry="28" fill="none" stroke="#2D3A35" stroke-width="2" />
      <ellipse cx="110" cy="110" rx="36" ry="74" fill="none" stroke="#2D3A35" stroke-width="2" />
      <line x1="36" y1="110" x2="184" y2="110" stroke="#2D3A35" stroke-width="2" />
      <line x1="110" y1="36" x2="110" y2="184" stroke="#2D3A35" stroke-width="2" />
      {/* continents abstract */}
      <path d="M70 90 q12 6 14 18 q-10 14 -28 8z" fill="#FFF8F4" opacity="0.45" />
      <path d="M134 78 q10 8 6 18 q-12 4 -16 -10z" fill="#FFF8F4" opacity="0.45" />
      <path d="M120 132 q14 4 18 16 q-16 8 -28 -2z" fill="#FFF8F4" opacity="0.45" />
      {/* vine */}
      <g fill="none" stroke="#2D3A35" stroke-width="2.4" stroke-linecap="round">
        <path d="M30 160 q40 -40 90 -20 q40 18 80 -10" />
      </g>
      <g fill="#A8E6CF" stroke="#2D3A35" stroke-width="2">
        <path d="M50 142 q-6 -6 0 -12 q6 6 0 12z" />
        <path d="M82 142 q-6 8 -14 4 q4 -10 14 -4z" />
        <path d="M134 156 q6 8 14 4 q-4 -10 -14 -4z" />
        <path d="M168 140 q6 -8 14 -4 q-4 10 -14 4z" />
      </g>
      {/* coral tips */}
      <circle cx="30" cy="158" r="4" fill="#FF6F5E" />
      <circle cx="200" cy="150" r="4" fill="#FF6F5E" />
    </svg>
  );
}

export function EnvelopeBloom(props) {
  return (
    <svg viewBox="0 0 320 280" width={props.width ?? 300} height={props.height ?? 280} xmlns="http://www.w3.org/2000/svg" class={props.class} aria-hidden="true">
      {/* envelope back */}
      <rect x="40" y="100" width="240" height="150" rx="14" fill="#FFCBA4" stroke="#2D3A35" stroke-width="2.5" />
      {/* envelope opening flap (open) */}
      <path d="M40 100 L160 30 L280 100 L160 178 Z" fill="#FFE3CE" stroke="#2D3A35" stroke-width="2.5" stroke-linejoin="round" />
      {/* card inside */}
      <rect x="84" y="50" width="152" height="130" rx="10" fill="#FFF8F4" stroke="#2D3A35" stroke-width="2.4" />
      {/* card line decor */}
      <line x1="100" y1="78" x2="220" y2="78" stroke="#5BC8D0" stroke-width="3" stroke-linecap="round" />
      <line x1="100" y1="94" x2="180" y2="94" stroke="#A8E6CF" stroke-width="3" stroke-linecap="round" />
