// All inline-SVG illustrations for Lumi & Bloom.
// Each component returns a self-contained SVG so it can be reused across pages.

export function BloomMotif(props) {
  const size = props.size ?? 480;
  return (
    <svg
      viewBox="0 0 480 480"
      width={size}
      height={size}
      xmlns="http://www.w3.org/2000/svg"
      class={props.class}
      aria-hidden="true"
    >
      <defs>
        <radialGradient id="bloomCore" cx="50%" cy="50%" r="50%">
          <stop offset="0%" stop-color="#FFFBEA" />
          <stop offset="60%" stop-color="#FFE566" />
          <stop offset="100%" stop-color="#FFCBA4" />
        </radialGradient>
        <linearGradient id="petalA" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#FF8E7E" />
          <stop offset="100%" stop-color="#FF6F5E" />
        </linearGradient>
        <linearGradient id="petalB" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stop-color="#FFCBA4" />
          <stop offset="100%" stop-color="#FF8E7E" />
        </linearGradient>
      </defs>

      {/* outer petals */}
      <g class="spin-slow" style="transform-origin: 240px 240px;">
        {Array.from({ length: 12 }).map((_, i) => {
          const angle = (i * 360) / 12;
          return (
            <ellipse
              cx="240"
              cy="100"
              rx="34"
              ry="86"
              fill="url(#petalA)"
              opacity="0.9"
              transform={`rotate(${angle} 240 240)`}
            />
          );
        })}
      </g>
      {/* inner petals */}
      <g class="spin-slow-rev" style="transform-origin: 240px 240px;">
        {Array.from({ length: 8 }).map((_, i) => {
          const angle = (i * 360) / 8 + 22.5;
          return (
            <ellipse
              cx="240"
              cy="148"
              rx="22"
              ry="60"
              fill="url(#petalB)"
              opacity="0.92"
              transform={`rotate(${angle} 240 240)`}
            />
          );
        })}
      </g>
      {/* leaf accents */}
      <g class="drift" style="transform-origin: 240px 240px;">
        {[40, 130, 220, 310].map((a) => (
          <path
            d="M240 50 q-10 18 0 36 q10 -18 0 -36 z"
            fill="#A8E6CF"
            transform={`rotate(${a} 240 240) translate(0 -50)`}
          />
        ))}
      </g>
      {/* center glow */}
      <circle cx="240" cy="240" r="90" fill="url(#bloomCore)" />
      <circle cx="240" cy="240" r="46" fill="#FFF8F4" opacity="0.55" />
      <circle cx="240" cy="240" r="18" fill="#FFE566" />
      {/* tiny sparkles */}
      <g fill="#FFE566">
        <circle cx="120" cy="80" r="5" />
        <circle cx="380" cy="120" r="4" />
        <circle cx="400" cy="340" r="6" />
        <circle cx="80" cy="340" r="4" />
        <circle cx="60" cy="200" r="3" />
        <circle cx="420" cy="220" r="3" />
      </g>
    </svg>
  );
}

