        <circle cx="82" cy="68" r="11" />
        <circle cx="118" cy="68" r="11" />
        <circle cx="88" cy="50" r="10" />
        <circle cx="112" cy="50" r="10" />
      </g>
      <circle cx="100" cy="60" r="6" fill="#FFE566" stroke="#2D3A35" stroke-width="2" />
    </svg>
