}

export function GlobeVine(props) {
  return (
    <svg viewBox="0 0 220 220" width={props.size ?? 200} height={props.size ?? 200} xmlns="http://www.w3.org/2000/svg" class={props.class} aria-hidden="true">
      {/* globe */}
      <circle cx="110" cy="110" r="74" fill="#A8E6CF" stroke="#2D3A35" stroke-width="2.5" />
      <ellipse cx="110" cy="110" rx="74" ry="28" fill="none" stroke="#2D3A35" stroke-width="2" />
      <ellipse cx="110" cy="110" rx="36" ry="74" fill="none" stroke="#2D3A35" stroke-width="2" />
      <line x1="36" y1="110" x2="184" y2="110" stroke="#2D3A35" stroke-width="2" />
      <line x1="110" y1="36" x2="110" y2="184" stroke="#2D3A35" stroke-width="2" />
      {/* continents abstract */}
      <path d="M70 90 q12 6 14 18 q-10 14 -28 8z" fill="#FFF8F4" opacity="0.45" />
      <path d="M134 78 q10 8 6 18 q-12 4 -16 -10z" fill="#FFF8F4" opacity="0.45" />
      <path d="M120 132 q14 4 18 16 q-16 8 -28 -2z" fill="#FFF8F4" opacity="0.45" />
      {/* vine */}
      <g fill="none" stroke="#2D3A35" stroke-width="2.4" stroke-linecap="round">
        <path d="M30 160 q40 -40 90 -20 q40 18 80 -10" />
      </g>
      <g fill="#A8E6CF" stroke="#2D3A35" stroke-width="2">
        <path d="M50 142 q-6 -6 0 -12 q6 6 0 12z" />
        <path d="M82 142 q-6 8 -14 4 q4 -10 14 -4z" />
        <path d="M134 156 q6 8 14 4 q-4 -10 -14 -4z" />
        <path d="M168 140 q6 -8 14 -4 q-4 10 -14 4z" />
      </g>
      {/* coral tips */}
      <circle cx="30" cy="158" r="4" fill="#FF6F5E" />
      <circle cx="200" cy="150" r="4" fill="#FF6F5E" />
    </svg>
  );
}

export function EnvelopeBloom(props) {
  return (
    <svg viewBox="0 0 320 280" width={props.width ?? 300} height={props.height ?? 280} xmlns="http://www.w3.org/2000/svg" class={props.class} aria-hidden="true">
      {/* envelope back */}
      <rect x="40" y="100" width="240" height="150" rx="14" fill="#FFCBA4" stroke="#2D3A35" stroke-width="2.5" />
      {/* envelope opening flap (open) */}
      <path d="M40 100 L160 30 L280 100 L160 178 Z" fill="#FFE3CE" stroke="#2D3A35" stroke-width="2.5" stroke-linejoin="round" />
      {/* card inside */}
      <rect x="84" y="50" width="152" height="130" rx="10" fill="#FFF8F4" stroke="#2D3A35" stroke-width="2.4" />
      {/* card line decor */}
      <line x1="100" y1="78" x2="220" y2="78" stroke="#5BC8D0" stroke-width="3" stroke-linecap="round" />
      <line x1="100" y1="94" x2="180" y2="94" stroke="#A8E6CF" stroke-width="3" stroke-linecap="round" />
      <line x1="100" y1="110" x2="200" y2="110" stroke="#A8E6CF" stroke-width="3" stroke-linecap="round" />
      {/* stem */}
      <line x1="160" y1="50" x2="160" y2="6" stroke="#2D3A35" stroke-width="2.4" stroke-linecap="round" />
      {/* leaf */}
      <path d="M160 32 q-12 -2 -14 -14 q14 -2 14 14z" fill="#A8E6CF" stroke="#2D3A35" stroke-width="2.2" />
      {/* flower */}
      <g fill="#FF6F5E" stroke="#2D3A35" stroke-width="2.2">
        <circle cx="160" cy="-2" r="14" />
        <circle cx="142" cy="8" r="11" />
        <circle cx="178" cy="8" r="11" />
        <circle cx="148" cy="-10" r="10" />
        <circle cx="172" cy="-10" r="10" />
      </g>
      <circle cx="160" cy="0" r="6" fill="#FFE566" stroke="#2D3A35" stroke-width="2" />
      {/* envelope front flap */}
      <path d="M40 250 L160 178 L280 250" fill="#FF8E7E" stroke="#2D3A35" stroke-width="2.5" stroke-linejoin="round" />
      {/* tiny sparkles */}
      <g fill="#FFE566">
        <circle cx="30" cy="40" r="3" />
        <circle cx="290" cy="60" r="4" />
        <circle cx="20" cy="220" r="3" />
        <circle cx="300" cy="200" r="3" />
