}

export function ProductMockup(props) {
  // A flat-lay style SVG of two products (a jar and a bottle), color-customizable via accent
  const accent = props.accent ?? '#FFCBA4';
  const label = props.label ?? '#FFF8F4';
  return (
    <svg viewBox="0 0 280 200" width="100%" height="100%" xmlns="http://www.w3.org/2000/svg" class={props.class} aria-hidden="true">
      {/* jar */}
      <g transform="translate(30 36)">
        <rect x="0" y="20" width="98" height="118" rx="14" fill={accent} stroke="#2D3A35" stroke-width="2.2" />
        {/* jar lid */}
        <rect x="-6" y="0" width="110" height="26" rx="8" fill="#2D3A35" />
        <rect x="0" y="6" width="98" height="14" rx="4" fill="#FFF8F4" opacity="0.18" />
        {/* label */}
        <rect x="10" y="50" width="78" height="60" rx="6" fill={label} stroke="#2D3A35" stroke-width="2" />
        <circle cx="49" cy="74" r="10" fill="#FF6F5E" />
        <circle cx="49" cy="74" r="4" fill="#FFE566" />
        <rect x="22" y="92" width="54" height="3.5" rx="2" fill="#2D3A35" opacity="0.6" />
        <rect x="32" y="100" width="34" height="3" rx="2" fill="#2D3A35" opacity="0.45" />
      </g>
      {/* bottle */}
      <g transform="translate(160 18)">
        <rect x="34" y="14" width="14" height="22" rx="3" fill="#2D3A35" />
        <rect x="22" y="32" width="38" height="14" rx="6" fill="#2D3A35" />
        <path d="M14 50 q0 -6 6 -6 h44 q6 0 6 6 v90 q0 14 -14 14 h-28 q-14 0 -14 -14 z" fill={accent} stroke="#2D3A35" stroke-width="2.2" />
        {/* label */}
        <rect x="20" y="74" width="44" height="44" rx="6" fill={label} stroke="#2D3A35" stroke-width="2" />
        <path d="M30 90 q12 -14 24 0" stroke="#FF6F5E" stroke-width="3" fill="none" stroke-linecap="round" />
        <circle cx="42" cy="102" r="2.5" fill="#2D3A35" />
      </g>
      {/* leaves */}
      <g fill="#A8E6CF" stroke="#2D3A35" stroke-width="1.8">
        <path d="M14 168 q14 -10 28 -2 q-14 10 -28 2z" />
        <path d="M236 32 q14 -10 28 -2 q-14 10 -28 2z" />
      </g>
      <circle cx="6" cy="186" r="3" fill="#FFE566" />
      <circle cx="262" cy="22" r="3" fill="#FFE566" />
    </svg>
  );
}

export function Icon({ name, stroke = '#2D3A35', fill = 'none', size = 28, strokeWidth = 1.8 }) {
  const common = { width: size, height: size, viewBox: '0 0 24 24', fill, stroke, 'stroke-width': strokeWidth, 'stroke-linecap': 'round', 'stroke-linejoin': 'round', 'aria-hidden': 'true' };
  switch (name) {
    case 'magnifying-glass':
      return (
        <svg {...common}>
          <circle cx="11" cy="11" r="6" />
          <path d="M20 20l-4.3-4.3" />
        </svg>
      );
    case 'leaf':
      return (
        <svg {...common}>
          <path d="M4 20c2-10 8-16 16-16-1 9-7 15-16 16z" />
          <path d="M4 20l8-8" />
        </svg>
      );
    case 'recycle':
      return (
        <svg {...common}>
          <path d="M7 7l3-5 3 5" />
          <path d="M14 7l3 5 3-5" />
          <path d="M3 14l4 4 4-4" />
          <path d="M7 18h10" />
          <path d="M12 2v12" />
        </svg>
      );
    case 'people':
      return (
        <svg {...common}>
          <circle cx="9" cy="8" r="3" />
          <circle cx="17" cy="9" r="2.5" />
          <path d="M3 19c0-3 3-5 6-5s6 2 6 5" />
          <path d="M14 19c0-2 2-4 4-4s3 2 3 4" />
