      );
    case 'jar':
      return (
        <svg {...common}>
          <rect x="6" y="8" width="12" height="13" rx="2" />
          <rect x="5" y="4" width="14" height="4" rx="1" />
          <path d="M9 13h6" />
        </svg>
      );
    case 'star':
      return (
        <svg {...common}>
          <path d="M12 2l2.9 6.1 6.6 0.7-4.9 4.6 1.3 6.6L12 16.9 6.1 20l1.3-6.6L2.5 8.8l6.6-0.7z" />
        </svg>
      );
    case 'globe':
      return (
        <svg {...common}>
          <circle cx="12" cy="12" r="9" />
          <path d="M3 12h18" />
          <path d="M12 3a14 14 0 010 18" />
          <path d="M12 3a14 14 0 000 18" />
        </svg>
      );
    case 'flask-x':
      return (
        <svg {...common}>
          <path d="M9 3h6" />
          <path d="M10 3v6L5 19a2 2 0 002 2h10a2 2 0 002-2L14 9V3" />
          <path d="M8 18l8-8" />
          <path d="M16 18l-8-8" />
        </svg>
      );
    case 'drop-x':
      return (
        <svg {...common}>
          <path d="M12 3c4 4 7 8 7 12a7 7 0 11-14 0c0-4 3-8 7-12z" />
          <path d="M9 13l6 6" />
          <path d="M15 13l-6 6" />
        </svg>
      );
    case 'wave':
      return (
        <svg {...common}>
          <path d="M3 14c2 0 3-2 5-2s3 2 5 2 3-2 5-2 3 2 5 2" />
          <path d="M3 9c2 0 3-2 5-2s3 2 5 2 3-2 5-2 3 2 5 2" />
        </svg>
      );
    case 'stethoscope':
      return (
        <svg {...common}>
          <path d="M6 3v8a5 5 0 0010 0V3" />
          <path d="M11 16v2a4 4 0 008 0v-3" />
          <circle cx="19" cy="14" r="2" />
        </svg>
      );
    case 'camera':
      return (
        <svg {...common}>
          <rect x="3" y="6" width="18" height="14" rx="3" />
          <circle cx="12" cy="13" r="4" />
          <path d="M8 6l1.5-2h5L16 6" />
        </svg>
      );
    case 'play':
      return (
        <svg {...common}>
          <circle cx="12" cy="12" r="9" />
          <path d="M10 8l6 4-6 4z" fill={stroke} stroke="none" />
        </svg>
      );
    case 'envelope-star':
      return (
        <svg {...common}>
          <rect x="3" y="6" width="18" height="13" rx="3" />
          <path d="M3 8l9 6 9-6" />
          <path d="M17 3l0.6 1.3L19 4.5l-1 1 0.2 1.4L17 6.2l-1.2 0.7 0.2-1.4-1-1 1.4-0.2z" fill={stroke} stroke="none" />
        </svg>
      );
    case 'speech':
      return (
        <svg {...common}>
          <path d="M4 7a3 3 0 013-3h7a3 3 0 013 3v4a3 3 0 01-3 3H9l-4 3v-3a3 3 0 01-1-2z" />
          <path d="M11 14h7a3 3 0 013 3v3l-3-2h-7" />
        </svg>
      );
    case 'mail':
      return (
        <svg {...common}>
          <rect x="3" y="5" width="18" height="14" rx="3" />
          <path d="M3 7l9 6 9-6" />
        </svg>
      );
    case 'arrow-right':
      return (
        <svg {...common}>
          <path d="M5 12h14" />
          <path d="M13 6l6 6-6 6" />
        </svg>
      );
    case 'bolt':
      return (
        <svg {...common}>
          <path d="M13 2L4 14h7l-1 8 9-12h-7z" />
        </svg>
      );
    case 'sparkle':
      return (
        <svg {...common}>
          <path d="M12 3v4M12 17v4M3 12h4M17 12h4M6 6l2 2M16 16l2 2M6 18l2-2M16 8l2-2" />
        </svg>
      );
    case 'check':
      return (
        <svg {...common}>
          <path d="M5 12l4 4 10-10" />
        </svg>
      );
    case 'plus':
      return (
        <svg {...common}>
          <path d="M12 5v14" />
