                <div class={`pl-16 lg:pl-0 ${i % 2 === 0 ? 'lg:text-right lg:pr-10' : 'lg:col-start-2 lg:pl-10'}`}>
                  <div class={`font-accent text-sunshine-butter text-[44px] sm:text-[56px] lg:text-[72px] leading-none ${i % 2 === 0 ? 'lg:-mr-4' : 'lg:-ml-4'}`}>
                    {m.year}
                  </div>
                  <h3 class="font-heading font-bold text-bloom-milk text-[20px] mt-3">{m.title}</h3>
                  <p class={`text-bloom-milk/75 text-[15px] leading-[1.65] mt-2 ${i % 2 === 0 ? 'lg:ml-auto' : ''} max-w-sm`}>{m.desc}</p>
                  <span class={`inline-block mt-4 px-4 py-1.5 rounded-full font-accent text-[10px] ${statusStyle(m.status)}`}>
                    {m.status}
                  </span>
                </div>
              </li>
            ))}
          </ol>
        </div>
      </div>
