import { render } from 'solid-js/web';
import { onMount, createSignal, createEffect } from 'solid-js';
import Nav from '../components/Nav';
import Footer from '../components/Footer';
import { GlobeVine, DotsPattern, Icon } from '../components/SvgAssets';
import { initReveal } from '../lib/reveal';
import '../styles/tailwind.css';

const stats = [
  { value: '78%', desc: 'Of our current packaging is made from recycled or recyclable materials.', color: 'text-lumi-coral' },
  { value: 'Carbon Neutral', desc: 'All shipping is carbon offset through a certified reforestation program.', color: 'text-aqua-bloom' },
  { value: '2026', desc: 'Our target year for 100% plastic-free packaging across the full range.', color: 'text-lumi-coral' },
  { value: '1% for Planet', desc: 'We donate 1% of annual revenue to environmental nonprofits through our giving program.', color: 'text-aqua-bloom' },
];

const pillars = [
  { title: 'Clean Formulation', desc: 'We source only responsibly harvested, sustainably farmed botanical ingredients. No petrochemical derivatives. Full supply chain transparency.', icon: 'leaf', bg: 'bg-sunshine-butter' },
  { title: 'Circular Packaging', desc: 'We use post-consumer recycled plastics, glass, and aluminum. Our refill program lets customers return empties for a discount on their next order.', icon: 'recycle', bg: 'bg-petal-mint' },
  { title: 'Climate Responsibility', desc: 'All operations and shipping are carbon offset. We publish our annual carbon footprint report so you can hold us accountable.', icon: 'globe', bg: 'bg-glow-peach' },
  { title: 'Community Giving', desc: "1% of every sale goes to environmental and women's wellness nonprofits selected by our customer community each year.", icon: 'people', bg: 'bg-aqua-bloom' },
];

const timeline = [
  { year: '2021', title: 'Recycled Packaging Introduced', desc: 'Switched to post-consumer recycled materials for all bottles and jars, eliminating virgin plastic from 60% of the range.', status: 'Complete' },
  { year: '2022', title: 'Carbon-Offset Shipping Launched', desc: 'Partnered with a certified reforestation program to offset 100% of shipping emissions on every order.', status: 'Complete' },
  { year: '2023', title: 'Refill Program Pilot', desc: 'Launched a refill program for our top three products, reducing single-use packaging by an estimated 18,000 units annually.', status: 'Complete' },
  { year: '2024', title: 'Full Refill Range Expansion', desc: 'Expanding the refill program to cover the entire product catalog. Estimated completion: Q3 2024.', status: 'In Progress' },
  { year: '2026', title: '100% Plastic-Free Pledge', desc: 'Full transition to glass, aluminum, and compostable materials across all products and shipping materials.', status: 'Planned' },
];

const statusStyle = (status) => {
  switch (status) {
    case 'Complete': return 'bg-petal-mint text-deep-petal';
    case 'In Progress': return 'bg-aqua-bloom text-deep-petal';
    case 'Planned': return 'bg-glow-peach text-deep-petal';
    default: return 'bg-bloom-milk text-deep-petal';
  }
};

function PageHeader() {
  return (
    <section
      id="sustainability-section-1"
      data-section-type="page_header"
      class="bg-petal-mint pt-36 lg:pt-40 pb-20 px-5 sm:px-8 text-center relative overflow-hidden"
    >
      <span class="absolute top-20 left-12 w-16 h-16 rounded-full bg-sunshine-butter/40 blur-2xl drift" />
      <span class="absolute bottom-20 right-12 w-20 h-20 rounded-full bg-lumi-coral/30 blur-2xl drift" style="animation-delay: -7s" />

      <div class="max-w-3xl mx-auto relative">
        <div class="flex justify-center mb-7 reveal">
          <GlobeVine class="bloom-float w-[140px] sm:w-[180px] lg:w-[200px] h-auto" />
        </div>
        <p class="font-accent text-[12px] text-deep-petal reveal reveal-delay-1">Our Planet Pledge</p>
        <h1 class="font-heading font-extrabold text-deep-petal text-[36px] sm:text-[48px] lg:text-[64px] leading-[1.1] tracking-tight mt-3 reveal reveal-delay-2">
          Good for Your Skin. <span class="text-lumi-coral">Better</span> for the Planet.
        </h1>
        <p class="text-deep-petal/80 mt-5 max-w-xl mx-auto text-[17px] sm:text-[18px] leading-[1.65] reveal reveal-delay-3">
          We believe beauty shouldn't cost the earth. Here's exactly what we're doing about it — and where we still have work to do.
        </p>
      </div>
    </section>
  );
}

function ProgressBars() {
  // Animate the bars filling in once visible.
  let containerRef;
  const [animated, setAnimated] = createSignal(false);
  onMount(() => {
    const obs = new IntersectionObserver((entries) => {
      entries.forEach((e) => {
        if (e.isIntersecting) {
          setAnimated(true);
          obs.disconnect();
        }
      });
    }, { threshold: 0.3 });
    if (containerRef) obs.observe(containerRef);
  });
  const bars = [
    { label: 'Recycled materials', pct: 78, color: 'bg-lumi-coral' },
    { label: 'Carbon-offset shipping', pct: 100, color: 'bg-aqua-bloom' },
    { label: 'Plastic-free goal · 2026', pct: 62, color: 'bg-sunshine-butter', dashed: true },
  ];
  return (
    <div ref={(el) => (containerRef = el)} class="mt-6 space-y-5">
      {bars.map((b) => (
        <div>
          <div class="flex justify-between text-[14px] mb-1.5">
            <span class="font-body text-deep-petal">{b.label}</span>
            <span class="font-accent text-[11px] text-deep-petal/70">{b.pct}%</span>
          </div>
          <div class="h-3 w-full bg-soft-cloud rounded-full overflow-hidden">
            <div
              class={`h-full ${b.color} ${b.dashed ? 'border-r-4 border-dashed border-deep-petal/40' : ''} rounded-full transition-[width] duration-[1800ms] ease-out`}
              style={`width: ${animated() ? b.pct + '%' : '0%'}`}
            />
          </div>
        </div>
      ))}
    </div>
  );
}

function Stats() {
  return (
    <section
      id="sustainability-section-2"
      data-section-type="stats"
      class="bg-bloom-milk py-20 lg:py-24 px-5 sm:px-8"
    >
      <div class="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-10 lg:gap-12 items-start">
        <div class="lg:col-span-7">
          <div class="grid grid-cols-2 gap-4">
            {stats.map((s, i) => (
              <div class={`reveal reveal-delay-${i + 1} bg-bloom-milk border-[1.5px] border-glow-peach rounded-[20px] p-6 lift-card`}>
                <div class={`font-heading font-extrabold leading-none text-[36px] sm:text-[44px] lg:text-[56px] ${s.color}`}>
                  {s.value}
                </div>
                <p class="text-deep-petal text-[14px] sm:text-[15px] leading-[1.6] mt-3">{s.desc}</p>
              </div>
            ))}
          </div>
        </div>
        <div class="lg:col-span-5 reveal">
          <p class="font-accent text-[12px] text-aqua-bloom">Our Impact So Far</p>
          <h2 class="font-heading font-bold text-deep-petal text-[28px] sm:text-[34px] lg:text-[36px] mt-2 tracking-tight">
            Progress We Can Actually Measure
          </h2>
          <ProgressBars />
        </div>
      </div>
    </section>
  );
}

function Pillars() {
  return (
    <section
      id="sustainability-section-3"
      data-section-type="feature_grid"
      class="bg-soft-cloud py-20 lg:py-24 px-5 sm:px-8"
    >
      <div class="max-w-7xl mx-auto">
        <div class="reveal">
          <p class="font-accent text-[12px] text-aqua-bloom">Our Four Pillars</p>
          <h2 class="font-heading font-bold text-deep-petal text-[28px] sm:text-[34px] lg:text-[38px] mt-2 tracking-tight">
            How We Think About Doing Better
          </h2>
          <p class="text-deep-petal/75 mt-3 max-w-xl text-[17px] leading-relaxed">
            Every sustainability decision at Lumi & Bloom runs through these four lenses.
          </p>
        </div>

        <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mt-12">
          {pillars.map((p, i) => (
            <article class={`reveal reveal-delay-${i + 1} bg-bloom-milk rounded-[24px] p-7 shadow-[var(--shadow-card)] lift-card`}>
              <div class={`w-12 h-12 rounded-xl ${p.bg} grid place-items-center mb-5`}>
                <Icon name={p.icon} stroke="#2D3A35" size={24} strokeWidth={2} />
              </div>
              <h3 class="font-heading font-bold text-deep-petal text-[20px]">{p.title}</h3>
              <p class="text-deep-petal/80 text-[15px] leading-[1.65] mt-2.5">{p.desc}</p>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

function Roadmap() {
  return (
    <section
      id="sustainability-section-4"
      data-section-type="timeline"
      class="bg-deep-petal text-bloom-milk py-20 lg:py-24 px-5 sm:px-8 relative overflow-hidden"
    >
      <div class="absolute inset-0 opacity-40">
        <DotsPattern color="#FFF8F4" opacity={0.05} />
      </div>
      <div class="relative max-w-5xl mx-auto">
        <div class="text-center reveal">
          <p class="font-accent text-[12px] text-petal-mint">The Roadmap</p>
          <h2 class="font-heading font-extrabold text-bloom-milk text-[28px] sm:text-[36px] lg:text-[44px] mt-2 tracking-tight">
            Where We've Been and Where We're Going
          </h2>
          <p class="text-bloom-milk/70 mt-3 max-w-lg mx-auto text-[16px] leading-relaxed">
            We share this publicly because accountability is part of the commitment.
          </p>
        </div>

        <div class="mt-14 relative">
          {/* spine */}
          <div class="absolute top-0 bottom-0 left-6 lg:left-1/2 lg:-translate-x-1/2 w-[2px] bg-aqua-bloom/50" />
          <ol class="space-y-10">
            {timeline.map((m, i) => (
