                <div class="absolute left-6 lg:left-1/2 -translate-x-1/2 top-10 w-3.5 h-3.5 rounded-full bg-aqua-bloom border-2 border-deep-petal z-10" />
                <div class={`pl-16 lg:pl-0 ${i % 2 === 0 ? 'lg:text-right lg:pr-10' : 'lg:col-start-2 lg:pl-10'}`}>
