for (const [path, png] of pages) {
  errs.length = 0;
  await page.goto(`http://127.0.0.1:3000/${path}`, { waitUntil: 'networkidle' });
  // verify body has data-page-slug
  const slug = await page.evaluate(() => document.body.getAttribute('data-page-slug'));
  const sections = await page.$$eval('section', (els) => els.map((e) => ({
    id: e.id,
    type: e.getAttribute('data-section-type'),
  })));
  console.log('===', path, 'slug=', slug);
  console.log(JSON.stringify(sections, null, 2));
  if (errs.length) console.log('ERRORS:', errs);
  await page.screenshot({ path: png, fullPage: false });
}

await browser.close();
EOF
