// IntersectionObserver-based reveal. Falls back to marking everything visible
// after a short delay so full-page screenshots and headless captures work.

let observer = null;

function setupObserver() {
  if (observer) return observer;
  observer = new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
          observer.unobserve(entry.target);
        }
      }
    },
    { threshold: 0.05, rootMargin: '0px 0px -4% 0px' }
  );
  return observer;
}

export function initReveal() {
  if (typeof window === 'undefined') return;
  const obs = setupObserver();
  const targets = document.querySelectorAll('.reveal:not(.is-visible)');
  targets.forEach((el) => obs.observe(el));

  // Safety net: if anything is still hidden after this delay (e.g. fullPage
  // screenshot tools that resize the viewport but skip observer ticks), reveal
  // it so the final layout is always visible to a static reader.
  window.setTimeout(() => {
    document.querySelectorAll('.reveal:not(.is-visible)').forEach((el) => {
      el.classList.add('is-visible');
    });
  }, 1500);
}

